mapper.select:
SELECT type,CAST(id AS CHAR) id,order_no,status,created_at FROM (
   SELECT 'PURCHASE' type,id,order_no,status,created_at FROM purchase_order WHERE operator_id=#{id} AND status IN ('DRAFT','PENDING','REJECTED')
   UNION ALL SELECT 'STOCKTAKE',id,order_no,status,created_at FROM stocktake_order WHERE operator_id=#{id} AND status IN ('COUNTING','PENDING','REJECTED')
  ) t ORDER BY created_at DESC,type,id DESC LIMIT #{q.pageSize} OFFSET #{q.offset}
